# Description:
# This Python script requires data generated by qPCR_pathogen_analysis.R.
#--------------------------------------------------------------


import pandas as pd
import networkx as nx
import matplotlib.pyplot as plt
from matplotlib.lines import Line2D
import matplotlib.colors as mcolors
import matplotlib.cm as cm

# Path to the CSV file
file_path = 'Antibiotic_transition.csv'

# Read the CSV file
data = pd.read_csv(file_path, sep=';', engine='python')

# Remove the first column by index (if unnecessary)
data = data.drop(data.columns[0], axis=1)

# Clean the 'Number' column
data['Number'] = data['Number'].astype(str).str.replace(' ', '').str.replace(',', '.').astype(float)

# Remove rows where 'From' or 'To' are NaN
data = data.dropna(subset=['From', 'To'])

# Ensure required columns exist
if 'From' not in data.columns or 'To' not in data.columns:
    raise ValueError("The columns 'From' or 'To' are missing from the DataFrame.")

# Create a directed graph
G = nx.DiGraph()

# Add edges with weights to the graph
for row in data.itertuples(index=False):
    source, target, value = row.From, row.To, row.Number
    if source != target:  # Exclude self-loops (where source == target)
        G.add_edge(source, target, weight=value)
    else:
        G.add_edge(source, target, weight=value)  # Explicitly add self-loops

# Define node positions
pos = {
    "A": (0, 2),
    "B": (0.5, 2),
    "C": (0, 0),
    "D": (0.5, 0),
    "E": (-0.25, 1),
    "F": (0.75, 1)
}

# Define node colors
node_colors = {
    "A": '#8da0cb',  # Blue
    "B": '#e0c900',  # Dark yellow
    "C": '#66c2a5',  # Green
    "D": '#fc8d62',  # Dark orange
    "E": '#a6d854',  # Light green
    "F": '#e78ac3'  # Pink
     }

# Assign node colors based on labels
node_color_list = [node_colors.get(node, '#000000') for node in G.nodes]

# Plot the graph
plt.figure(figsize=(12, 8))
edges = G.edges(data=True)

# Draw nodes with defined colors and circular shapes
nx.draw_networkx_nodes(G, pos, node_size=1200, node_color=node_color_list, node_shape='o')

# Draw node labels
nx.draw_networkx_labels(G, pos, font_size=16, font_weight='bold')


# Dictionnaire : nœud → (texte personnalisé, position x, position y)
node_annotations = {
    "A": ("No pathogen", -0.30, 1.95),
    "B": ("NAS", 0.61, 1.95),
    "C": ("C. bovis \nS. uberis", -0.2, -0.2),
    "D": ("C. bovis", 0.58, -0.1),
    "F": ("T.pyo./P.indo. \nand/or \nyeasts", 0.8, 0.74)
}

# Ajouter une annotation colorée à chaque nœud, avec texte et position personnalisés
for node, (label_text, x, y) in node_annotations.items():
    color = node_colors.get(node, '#000000')
    
    plt.text(
        x, y,
        label_text,
        fontsize=12,
        color=color,
        fontweight='bold'
    )


# Create a normalization object for edge colors (based on values 1, 2, or 3)
norm = mcolors.Normalize(vmin=1, vmax=3)  # Normalize for 1, 2, and 3 transitions
cmap = mcolors.ListedColormap(['lightgray', 'gray', 'black'])  # Colors for 1, 2, 3 transitions

# Create a ScalarMappable to map colors to 'Number' values
sm = plt.cm.ScalarMappable(cmap=cmap, norm=norm)
sm.set_array([])  # Required for ScalarMappable

# Draw edges with size and color proportional to 'Number'
ax = plt.gca()

# Create a slight offset to avoid overlapping arrows
for u, v, edge_data in edges:
    value = edge_data['weight']
    
    # Normalize 'Number' value for color mapping
    color = sm.to_rgba(value)  # Use the defined color scale
    arrow_size = 10 + 20 * (value / 3)  # Adjust arrow size proportionally

    # If the edge is a self-loop (From == To), adjust size and draw a smaller loop
    if u == v:
        # Reduce size for loops and draw a smaller circle
        circle_radius = 0.01 + 0.01 * value  # Adjusted size for loops
        nx.draw_networkx_edges(
            G, pos, edgelist=[(u, v)], arrowstyle='-|>', arrowsize=arrow_size, edge_color=[color],
            connectionstyle=f'arc3,rad=0.01', width=value * 2, ax=ax, node_size=1200
        )
    else:
        # Draw other arrows
        nx.draw_networkx_edges(
            G, pos, edgelist=[(u, v)], arrowstyle='-|>', arrowsize=arrow_size, edge_color=[color],
            connectionstyle=f'arc3,rad=0.1', width=value * 2, ax=ax, node_size=1200
        )

# Add a legend with 3 colored lines
legend_elements = [
    Line2D([0], [0], color='lightgray', lw=3, label='1 transition'),
    Line2D([0], [0], color='gray', lw=3, label='2 transitions'),
    Line2D([0], [0], color='black', lw=3, label='3 transitions')
]

# Add the legend to the graph
plt.legend(handles=legend_elements, loc='upper right', fontsize=12)

plt.title("")
plt.axis('off')  # Hide axes

# Save the graph as an image file
output_path = 'Figure_7.png'
plt.savefig(output_path, format='png', dpi=300)
